function groupAppointmentsByDay(list:any[]){
  const groups=new Map<string,{key:string;label:string;sortKey:string;items:any[]}>();
  for(const a of list){
    const d=new Date(a.start_at),dayKey=d.toLocaleDateString('en-CA',{timeZone:'Europe/Istanbul'});
    if(!groups.has(dayKey)){
      const label=`${dayNames[Number(new Date(dayKey+'T12:00:00').getDay())]} · ${d.toLocaleDateString('tr-TR',{day:'numeric',month:'long',timeZone:'Europe/Istanbul'})}`;
      groups.set(dayKey,{key:dayKey,label,sortKey:dayKey,items:[]});
    }
    groups.get(dayKey)!.items.push(a);
  }
  return Array.from(groups.values()).sort((a,b)=>a.sortKey.localeCompare(b.sortKey));
}
