 async function uploadLogo(file:File){const ext=file.name.split('.').pop(),path=`${currentBusiness.id}/logo-${Date.now()}.${ext}`;const{error}=await db.storage.from('business-media').upload(path,file,{upsert:true});if(error)return notify(error.message);const{data}=db.storage.from('business-media').getPublicUrl(path);await db.from('businesses').update({logo_url:data.publicUrl}).eq('id',currentBusiness.id);await load();notify('Logo yüklendi.')}
 async function uploadCover(file:File){const ext=file.name.split('.').pop(),path=`${currentBusiness.id}/cover-${Date.now()}.${ext}`;const{error}=await db.storage.from('business-media').upload(path,file);if(error)return notify(error.message);const{data}=db.storage.from('business-media').getPublicUrl(path);await db.from('businesses').update({cover_url:data.publicUrl,cover_type:file.type.startsWith('video/')?'video':'image'}).eq('id',currentBusiness.id);await load();notify('Kapak yüklendi.')}
 async function uploadGallery(files:FileList){for(const file of Array.from(files)){const ext=file.name.split('.').pop(),path=`${currentBusiness.id}/gallery-${Date.now()}-${Math.random().toString(36).slice(2)}.${ext}`;const{error}=await db.storage.from('business-media').upload(path,file);if(error){notify(error.message);continue}const{data}=db.storage.from('business-media').getPublicUrl(path);if(file.type.startsWith('video/'))await db.from('media_items').insert({business_id:currentBusiness.id,type:'video',url:data.publicUrl,title:`${currentBusiness.name} videosu`,sort_order:gallery.length});else await db.from('gallery_images').insert({business_id:currentBusiness.id,image_url:data.publicUrl,alt_text:`${currentBusiness.name} çalışması`,sort_order:gallery.length})}await load();notify('Galeri güncellendi.')}
 async function uploadAboutImages(files:FileList){
   const current:string[]=Array.isArray((business as any).about_images)?(business as any).about_images:[];
   const urls:string[]=[...current];
   for(const file of Array.from(files)){
     const ext=file.name.split('.').pop(),path=`${currentBusiness.id}/about-${Date.now()}-${Math.random().toString(36).slice(2)}.${ext}`;
     const{error}=await db.storage.from('business-media').upload(path,file);
     if(error){notify(error.message);continue}
     const{data}=db.storage.from('business-media').getPublicUrl(path);
     urls.push(data.publicUrl);
   }
   await db.from('businesses').update({about_images:urls,updated_at:new Date().toISOString()}).eq('id',currentBusiness.id);
   await load();notify('Hakkımızda fotoğrafları güncellendi.');
 }
 async function removeAboutImage(url:string){
   const current:string[]=Array.isArray((business as any).about_images)?(business as any).about_images:[];
   await db.from('businesses').update({about_images:current.filter(u=>u!==url),updated_at:new Date().toISOString()}).eq('id',currentBusiness.id);
   await load();notify('Fotoğraf kaldırıldı.');
 }
 async function removeBusinessMedia(field:'logo_url'|'cover_url'){await db.from('businesses').update({[field]:null}).eq('id',currentBusiness.id);await load();notify('Görsel kaldırıldı.')}
 async function removeGalleryImage(id:string){await db.from('gallery_images').delete().eq('id',id);await load();notify('Fotoğraf kaldırıldı.')}async function removeMediaItem(id:string){await db.from('media_items').delete().eq('id',id);await load();notify('Video kaldırıldı.')}
 async function addBlogPost(){const slug='yazi-'+Date.now().toString(36);const{data,error}=await db.from('blog_posts').insert({business_id:currentBusiness.id,slug,title:'Yeni Yazı',sort_order:blogPosts.length}).select().single();if(error)return notify(error.message);setBlogPosts(prev=>[...prev,data]);notify('Yazı eklendi.')}
 function updateBlogPost(id:string,patch:any){setBlogPosts(prev=>prev.map(p=>p.id===id?{...p,...patch}:p));if(blogTimers.current[id])clearTimeout(blogTimers.current[id]);blogTimers.current[id]=setTimeout(async()=>{await db.from('blog_posts').update({...patch,updated_at:new Date().toISOString()}).eq('id',id)},600)}
