 async function uploadBlogCover(id:string,file:File){const ext=file.name.split('.').pop(),path=`${currentBusiness.id}/blog-${id}-${Date.now()}.${ext}`;const{error}=await db.storage.from('business-media').upload(path,file);if(error)return notify(error.message);const{data}=db.storage.from('business-media').getPublicUrl(path);await db.from('blog_posts').update({cover_url:data.publicUrl}).eq('id',id);setBlogPosts(prev=>prev.map(p=>p.id===id?{...p,cover_url:data.publicUrl}:p));notify('Kapak yüklendi.')}
 async function persistService(row:any,id?:string){const q=id?db.from('services').update(row).eq('id',id):db.from('services').insert(row),{error}=await q;if(error)notify(error.message);else{setEditService(null);await load();notify('Hizmet kaydedildi.')}}
 async function saveHours(){for(const h of hours)await db.from('working_hours').update({is_open:h.is_open,start_time:h.start_time,end_time:h.end_time}).eq('id',h.id);await syncStaffHoursQuiet();notify('Çalışma saatleri kaydedildi ve tüm çalışanlara uygulandı.')}
 async function selectScheduleTarget(id:string){
   setScheduleTarget(id);
   if(id==='business')return;
   const{data}=await db.from('staff_working_hours').select('*').eq('staff_id',id).order('day_of_week');
   if(data?.length){setStaffScheduleHours(data)}
   else{
     // Bu çalışanın kendi saati hiç oluşturulmamış - dükkan saatlerinden başlat
     setStaffScheduleHours(hours.map(h=>({day_of_week:h.day_of_week,is_open:h.is_open,start_time:h.start_time,end_time:h.end_time})));
   }
 }
 async function saveStaffHours(){
   for(const h of staffScheduleHours){
     await db.from('staff_working_hours').upsert({staff_id:scheduleTarget,day_of_week:h.day_of_week,is_open:h.is_open,start_time:h.start_time,end_time:h.end_time},{onConflict:'staff_id,day_of_week'});
   }
   notify('Çalışanın saatleri kaydedildi.');
 }
 async function syncStaffHoursQuiet(){const staffIds=staffList.map(s=>s.id);if(!staffIds.length)return;for(const h of hours){await db.from('staff_working_hours').update({is_open:h.is_open,start_time:h.start_time,end_time:h.end_time}).in('staff_id',staffIds).eq('day_of_week',h.day_of_week)}await load()}
