 async function applyCatalogTheme(t:any){const palette=t.config?.palette||{},family=t.layout_family,heroMap:any={heritage:'centered',modern:'text_left',editorial:'text_right',soft:'centered',luxury:'centered',pop:'centered',zen:'text_only',fresh:'text_left',calm:'centered'},galleryMap:any={heritage:'showcase',modern:'grid',editorial:'masonry',soft:'grid',luxury:'showcase',pop:'grid',zen:'showcase',fresh:'grid',calm:'grid'};await db.from('businesses').update({selected_theme_id:t.id,primary_color:palette.primary||business?.primary_color,background_color:palette.background||business?.background_color,text_color:palette.text||business?.text_color,font_family:t.config?.heading_font==='serif'?'serif':t.config?.heading_font==='display'?'display':'sans',hero_layout:heroMap[family]||'text_left',gallery_layout:galleryMap[family]||'grid',hero_visual_mode:'none',updated_at:new Date().toISOString()}).eq('id',currentBusiness.id);const cfg={...(currentBusiness.draft_site_config||{}),themeId:t.id,layoutFamily:family,themeConfig:t.config,colors:{...(currentBusiness.draft_site_config?.colors||{}),...palette}};await db.rpc('save_site_draft',{p_business_id:currentBusiness.id,p_config:cfg});await load();notify(`${t.name} teması uygulandı.`)}
