function ratingWaLink(a:any){let p=String(a.customer_phone||'').replace(/\D/g,'');if(p.startsWith('0'))p='90'+p.slice(1);const site=process.env.NEXT_PUBLIC_SITE_URL||(typeof window!=='undefined'?window.location.origin:'');const url=`${site}/puan/${a.rating_token}`;const text=`Merhaba ${a.customer_first_name}, ${business?.name||''}'i tercih ettiğiniz için teşekkür ederiz! Deneyiminizi 1 dakikada puanlar mısınız?\n${url}`;return`https://wa.me/${p}?text=${encodeURIComponent(text)}`}
function reminderWaLink(a:any,businessName:string){let p=String(a.customer_phone||'').replace(/\D/g,'');if(p.startsWith('0'))p='90'+p.slice(1);const saat=new Date(a.start_at).toLocaleTimeString('tr-TR',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Istanbul'});const text=`Merhaba ${a.customer_first_name}, hatırlatma: ${businessName}'de saat ${saat} için randevunuz var (${a.services?.name||''}). Sizi bekliyoruz!`;return`https://wa.me/${p}?text=${encodeURIComponent(text)}`}
