 async function addManualAppointment(e:React.FormEvent<HTMLFormElement>){e.preventDefault();if(manualSubmittingRef.current)return;manualSubmittingRef.current=true;setManualSubmitting(true);try{const f=new FormData(e.currentTarget),payload:any={businessId:currentBusiness.id,serviceId:f.get('serviceId'),staffId:f.get('staffId'),date:f.get('date'),time:f.get('time'),firstName:f.get('firstName'),lastName:f.get('lastName'),phone:f.get('phone'),email:f.get('email'),note:f.get('note'),forceOverlap:false};let r=await fetch('/api/admin/appointments',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),j=await r.json().catch(()=>({}));if(r.status===409&&j.conflict){if(!confirm('Bu saatte başka bir randevu var. Yine de eklemek istiyor musun?')){return}payload.forceOverlap=true;r=await fetch('/api/admin/appointments',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});j=await r.json().catch(()=>({}))}if(!r.ok)return notify(j.error||'Randevu eklenemedi.');setManualOpen(false);setManualDate('');setManualServiceId('');setManualStaffId('');setManualTime('');await load();notify('Manuel randevu eklendi.')}finally{manualSubmittingRef.current=false;setManualSubmitting(false)}}
