 async function inviteStaff(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);let photoUrl='';const photo=f.get('photo') as File;if(photo?.size){const ext=photo.name.split('.').pop(),path=`${currentBusiness.id}/staff-${Date.now()}.${ext}`,up=await db.storage.from('business-media').upload(path,photo);if(up.error)return notify(up.error.message);photoUrl=db.storage.from('business-media').getPublicUrl(path).data.publicUrl}const serviceIds=services.filter(s=>f.get(`service_${s.id}`)==='on').map(s=>s.id),phone=String(f.get('phone')||''),name=String(f.get('name')||''),username=String(f.get('username')||''),email=String(f.get('email')||''),r=await fetch('/api/admin/staff',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({businessId:currentBusiness.id,name,username:username||undefined,email:email||undefined,phone,title:f.get('title'),bio:f.get('bio'),photoUrl,serviceIds})}),j=await r.json();if(!r.ok)return notify(j.error);setStaffForm(false);await load();if(j.loginEmail)setNewStaffCredentials({name,phone,email:j.loginEmail,password:j.generatedPassword,loginUrl:j.loginUrl});else notify('Çalışan eklendi.')}
